initial_condition:
with {
    the SUT in the "initial state"
}

test_cases.then:
then {
    the SUT sends a valid Response containing:
        Response Body containing the type 'https://uri.etsi.org/ngsi-ld/errors/ResourceNotFound' and
        Response body containing 'title' element and
        Response Status Code set to 404
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/entities/{id}'
        method set to 'DELETE'
        Delete Entity Request with id set to '${entity_id}'
}
